// src/component_aiiot/Aiiot_index.js

import React, { useEffect } from 'react';
import './Aiiot.css'; // Import the CSS file

const AiIotInnovationCenter = () => {

  useEffect(() => {
    // 1. Initialize Feather Icons
    // We check if 'feather' is available on the window object
    if (window.feather) {
      window.feather.replace();
    }

    // 2. --- REVEAL ON SCROLL ---
    const scrollElements = document.querySelectorAll(".reveal-on-scroll");
    const elementInView = (el, dividend = 1) => {
      const elementTop = el.getBoundingClientRect().top;
      return (elementTop <= (window.innerHeight || document.documentElement.clientHeight) / dividend);
    };
    const displayScrollElement = (element) => element.classList.add("is-visible");
    
    const handleScrollAnimation = () => {
      scrollElements.forEach((el) => {
        if (elementInView(el, 1.25)) displayScrollElement(el);
      });
    };
    handleScrollAnimation(); // Initial check on load
    window.addEventListener("scroll", handleScrollAnimation);


    // 3. --- DYNAMIC HERO IMAGE CAROUSEL ---
    let autoSlideInterval; // Declare interval variable in a scope accessible by cleanup
    let carouselListeners = []; // To store listeners for cleanup

    async function setupCarousel() {
      const heroImage = document.getElementById('hero-image');
      const indicatorContainer = document.getElementById('carousel-indicators');
      const heroImageContainer = document.getElementById('hero-image-container');
      
      if (!heroImage || !indicatorContainer || !heroImageContainer) {
        console.error("Carousel elements not found!");
        return;
      }

      let heroImages = [];
      let currentImageIndex = 0;

      try {
        // IMPORTANT: This assumes 'carousel-images' is in your 'public' folder
        const response = await fetch('/carousel-images/carousel-images.json');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        heroImages = await response.json();

        if (heroImages.length === 0) {
          heroImageContainer.style.display = 'none';
          return;
        }

      } catch (error) {
        console.error("Could not load carousel images:", error);
        heroImage.src = "https://placehold.co/1200x600/f0f9ff/334155?text=Image+Not+Available";
        heroImageContainer.style.display = 'block';
        indicatorContainer.style.display = 'none';
        return;
      }
      
      // --- Carousel Logic (runs only if images are loaded successfully) ---
      indicatorContainer.innerHTML = heroImages.map((_, index) => 
        `<div class="indicator w-3 h-3 rounded-full bg-blue-300 cursor-pointer" data-index="${index}"></div>`
      ).join('');
      const indicators = indicatorContainer.querySelectorAll('.indicator');

      const updateIndicators = () => {
        indicators.forEach((indicator, index) => {
          indicator.classList.toggle('bg-blue-600', index === currentImageIndex);
          indicator.classList.toggle('active', index === currentImageIndex);
          indicator.classList.toggle('bg-blue-300', index !== currentImageIndex);
        });
      };

      const changeImage = () => {
        heroImage.style.opacity = '0.4';
        heroImage.style.transform = 'scale(1.03)';
        setTimeout(() => {
          // This path assumes 'carousel-images' is in the 'public' folder
          heroImage.src = heroImages[currentImageIndex].src;
          heroImage.alt = heroImages[currentImageIndex].alt;
          updateIndicators();
          heroImage.style.opacity = '1';
          heroImage.style.transform = 'scale(1)';
        }, 500);
      };

      const nextSlide = () => {
        currentImageIndex = (currentImageIndex + 1) % heroImages.length;
        changeImage();
      };

      const startAutoSlide = () => {
        clearInterval(autoSlideInterval);
        autoSlideInterval = setInterval(nextSlide, 4000);
      };

      const goToSlide = (index) => {
        if (index === currentImageIndex) return;
        currentImageIndex = index;
        changeImage();
        startAutoSlide(); // Reset interval
      };

      // Event Listeners
      indicators.forEach(indicator => {
        const listener = (e) => goToSlide(parseInt(e.target.dataset.index));
        indicator.addEventListener('click', listener);
        carouselListeners.push({ target: indicator, event: 'click', func: listener });
      });

      const handleMouseEnter = () => clearInterval(autoSlideInterval);
      const handleMouseLeave = () => startAutoSlide();
      
      heroImageContainer.addEventListener('mouseenter', handleMouseEnter);
      heroImageContainer.addEventListener('mouseleave', handleMouseLeave);
      carouselListeners.push({ target: heroImageContainer, event: 'mouseenter', func: handleMouseEnter });
      carouselListeners.push({ target: heroImageContainer, event: 'mouseleave', func: handleMouseLeave });

      // Initial setup
      changeImage(); // Load the first image
      startAutoSlide();
    }

    // Run the carousel setup
    setupCarousel();

    // 4. --- Cleanup Function ---
    // This runs when the component unmounts
    return () => {
      window.removeEventListener("scroll", handleScrollAnimation);
      clearInterval(autoSlideInterval);
      
      // Remove all dynamically added carousel listeners
      carouselListeners.forEach(listener => {
        listener.target.removeEventListener(listener.event, listener.func);
      });
    };

  }, []); // Empty dependency array means this runs once when the component mounts

  // Error handler function for images
  const onImageError = (e) => {
    e.target.onerror = null; // Prevent infinite loop
    e.target.src = 'https://placehold.co/128x128/e0e0e0/000000?text=Faculty';
  };

  return (
    <div className="min-h-screen flex flex-col text-slate-700 antialiased">
      {/* Header Section */}
      <header className="sticky top-0 z-50 w-full bg-white/80 backdrop-blur-lg border-b border-slate-200/80">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <nav className="flex justify-between items-center h-16">
            {/* Logo */}
            <a href="#hero" className="flex items-center gap-2 text-xl md:text-2xl font-bold text-blue-600">
              <svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"></path></svg>
              <span className="hidden sm:inline">Center for AI-IoT Innovation</span>
              <span className="sm:hidden">AI-IoT Center</span>
            </a>
            {/* Desktop Navigation Links */}
            <div className="hidden md:flex items-center space-x-4">
              <ul className="flex items-center space-x-8">
                <li><a href="#about" className="text-slate-600 hover:text-blue-600 font-medium transition duration-300">About</a></li>
                <li><a href="#faculty" className="text-slate-600 hover:text-blue-600 font-medium transition duration-300">Faculty</a></li>
                <li><a href="#projects" className="text-slate-600 hover:text-blue-600 font-medium transition duration-300">Projects</a></li>
                <li><a href="#contact" className="text-slate-600 hover:text-blue-600 font-medium transition duration-300">Contact</a></li>
              </ul>
              {/* CTA Buttons */}
              <div className="flex items-center space-x-2">
                <a href="https://airaware-app-gcw7.onrender.com/" target="_blank" rel="noopener noreferrer" className="bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AirAware</a>
                <a href="https://app.aiiot.it.com/aws" target="_blank" rel="noopener noreferrer" className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AWS</a>
              </div>
            </div>
            {/* Mobile Menu Button */}
            <button className="md:hidden text-slate-600 hover:text-blue-600" aria-label="Open menu">
              <i data-feather="menu"></i>
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow">
        {/* Hero Section */}
        <section id="hero" className="relative hero-gradient py-20 md:py-32">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
            <h1 className="text-4xl md:text-6xl font-extrabold text-slate-800 mb-4 leading-tight reveal-on-scroll">
              <span className="block text-2xl md:text-4xl font-medium text-slate-600">Sponsored by</span>
              <span className="text-blue-600">Ministry of Electronics and Information Technology</span>
            </h1>
            <p className="text-lg md:text-xl text-slate-600 mb-10 max-w-3xl mx-auto reveal-on-scroll" style={{ transitionDelay: '150ms' }}>
              The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI).
            </p>
            <div className="flex flex-col sm:flex-row justify-center items-center gap-4 mb-12 reveal-on-scroll" style={{ transitionDelay: '300ms' }}>
              <a href="#projects" className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105">Explore Projects</a>
              <a href="#about" className="w-full sm:w-auto bg-white hover:bg-slate-100 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105">Learn More</a>
            </div>
            {/* Container for the image carousel */}
            <div id="hero-image-container" className="relative max-w-5xl mx-auto reveal-on-scroll" style={{ transitionDelay: '450ms' }}>
              <div className="absolute -inset-2 bg-gradient-to-r from-blue-400 to-indigo-500 rounded-2xl blur-lg opacity-25"></div>
              <div className="relative w-full h-auto overflow-hidden rounded-xl shadow-2xl">
                {/* Note: src will be set by the useEffect hook */}
                <img id="hero-image" src="/carousel-images/1 (1).jpg" alt="AI-IoT Innovation Technology" width="1200" height="600" className="w-full h-auto object-cover transition-all duration-1000 ease-in-out" />
              </div>
              <div id="carousel-indicators" className="flex justify-center mt-6 space-x-3"></div>
            </div>
          </div>
        </section>

        {/* About Section */}
        <section id="about" className="py-20 bg-white">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="text-center mb-12 reveal-on-scroll">
              <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">About Our Center</h2>
              <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">Pioneering research where intelligence meets connectivity.</p>
            </div>
            <div className="grid md:grid-cols-2 gap-12 items-center">
              <div className="reveal-on-scroll">
                <div className="rounded-xl overflow-hidden shadow-lg border border-slate-200">
                  <img src="/carousel-images/1 (4).jpg" alt="Collaborative team working in a modern tech lab" loading="lazy" width="800" height="600" className="w-full h-auto object-cover" />
                </div>
              </div>
              <div className="text-lg text-slate-600 space-y-6 reveal-on-scroll" style={{ transitionDelay: '150ms' }}>
                <p>The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI). The lab is equipped with hardware development tools, computing systems, and educational resources to support research and development in this area. The center provides resources for both theoretical research and practical applications, aiming to advance the integration of AI technologies with IoT systems.</p>
                <p>We provide a state-of-the-art environment equipped with powerful computing resources and hardware development tools. This fosters a culture of innovation, empowering researchers and students to build the next generation of smart solutions.</p>
              </div>
            </div>
          </div>
        </section>

        {/* Faculty Section */}
        <section id="faculty" className="py-20 bg-slate-50">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="text-center mb-12 reveal-on-scroll">
              <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">Meet Our Expert Faculty</h2>
              <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">The brilliant minds leading our research and innovation.</p>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
              
              {/* Faculty Card 1 */}
              <div className="text-center bg-white p-6 rounded-xl shadow-md border border-slate-200 transform transition duration-300 hover:-translate-y-2 hover:shadow-xl reveal-on-scroll">
                <a href="https://www.adishankara.ac.in/department/faculty/25" target="_blank" rel="noopener noreferrer" className="block">
                  <img className="w-32 h-32 mx-auto rounded-full mb-4 object-cover shadow-lg" src="/faculties/ajay.jpeg" alt="Photo of Dr. Ajay Kumar" loading="lazy" width="128" height="128" onError={onImageError} />
                </a>
                <a href="https://www.adishankara.ac.in/department/faculty/25" target="_blank" rel="noopener noreferrer" className="hover:text-blue-800 transition duration-300"><h4 className="text-xl font-bold text-blue-700">Dr. Ajay Kumar</h4></a>
                <p className="text-slate-500 font-medium mb-2">Principal Investigator</p>
                <p className="text-slate-600 text-sm mb-4">Dr. Ajay Kumar is an Associate Professor at ASIET with a PhD in Electronics and Communication Engineering. His research interests include IoT and Wireless Sensor Networks.</p>
